#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

int main(void) {
    size_t count = (SIZE_MAX / 4) + 2;      /* 恶意大值 */
    size_t bytes = count * sizeof(int);     /* 乘法回绕，结果远小于期望 */

    printf("count = %zu\n", count);
    printf("count * sizeof(int) 回绕后 = %zu\n", bytes);
    printf("期望值应约为 %zu 字节 —— 说明乘法已溢出\n", count * 4);

    if (count > SIZE_MAX / sizeof(int)) {
        printf("正确防护：检测到溢出，拒绝分配\n");
    }
    return 0;
}
